/* Public official factories; caller owns every destination, initialized on errors. */
#include "platform.h"
#include "gnunet_util_lib.h"
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
static void hex(const char*s){if(!s){putchar('-');return;}for(const unsigned char*p=(const unsigned char*)s;*p;p++)printf("%02x",*p);}
static char **watched_file,**watched_config;
static void log_target(void*cls,enum GNUNET_ErrorType kind,const char*component,const char*date,const char*message){(void)cls;(void)component;(void)date;printf("OBS %d FILE ",kind);hex(*watched_file);printf(" CFG ");hex(*watched_config);printf(" MSG ");hex(message);putchar('\n');}
int main(int argc,char**argv){int flag=7;unsigned int inc=UINT_MAX,u=123;uint16_t small=456;unsigned long long big=789;char*string=NULL,*file=NULL,*config=NULL,*logfile=NULL,*level=NULL;struct GNUNET_TIME_Relative relative={111};struct GNUNET_TIME_Absolute absolute={222};struct GNUNET_TIME_Timestamp timestamp={.abs_time={333}};unsigned char data[3]={0xaa,0xbb,0xcc};GNUNET_TIME_set_offset(444);
 if(getenv("OWNED_HELPER_DIAGNOSTICS")){watched_file=&file;watched_config=&config;if(GNUNET_OK!=GNUNET_log_setup("owned-helper","DEBUG",NULL))return 4;GNUNET_logger_add(log_target,NULL);}
 struct GNUNET_GETOPT_CommandLineOption options[]={
 (getenv("OWNED_HELPER_MODIFIERS")?GNUNET_GETOPT_option_mandatory(GNUNET_GETOPT_option_flag('f',"flag","flag description",&flag)):GNUNET_GETOPT_option_flag('f',"flag","flag description",&flag)),(getenv("OWNED_HELPER_MODIFIERS")?GNUNET_GETOPT_option_exclusive(GNUNET_GETOPT_option_increment_uint('n',"number","increment description",&inc)):GNUNET_GETOPT_option_increment_uint('n',"number","increment description",&inc)),GNUNET_GETOPT_option_uint('u',"uint","NUMBER","uint description",&u),GNUNET_GETOPT_option_uint16('t',"small","NUMBER","small description",&small),GNUNET_GETOPT_option_ulong('g',"large","NUMBER","large description",&big),GNUNET_GETOPT_option_string('s',"string","TEXT","string description",&string),GNUNET_GETOPT_option_filename('F',"filename","FILENAME","filename description",&file),GNUNET_GETOPT_option_relative_time('R',"relative","TIME","relative description",&relative),GNUNET_GETOPT_option_absolute_time('A',"absolute","TIME","absolute description",&absolute),GNUNET_GETOPT_option_timestamp('S',"timestamp","TIME","timestamp description",&timestamp),GNUNET_GETOPT_option_timetravel('T',"travel"),GNUNET_GETOPT_option_base32_fixed_size('b',"bytes","BASE32","bytes description",data,sizeof data),GNUNET_GETOPT_option_verbose(&inc),GNUNET_GETOPT_option_cfgfile(&config),GNUNET_GETOPT_option_logfile(&logfile),GNUNET_GETOPT_option_loglevel(&level),GNUNET_GETOPT_option_help(GNUNET_OS_project_data_gnunet(),"Owned helpers"),GNUNET_GETOPT_option_version("0.29.1"),GNUNET_GETOPT_OPTION_END};
 int result=GNUNET_GETOPT_run("owned helpers",options,(unsigned)argc,argv);printf("RET %d VALUES %d %u %u %u %llu %llu %llu %llu %lld BYTES %02x%02x%02x\nSTR ",result,flag,inc,u,(unsigned)small,big,(unsigned long long)relative.rel_value_us,(unsigned long long)absolute.abs_value_us,(unsigned long long)timestamp.abs_time.abs_value_us,GNUNET_TIME_get_offset(),data[0],data[1],data[2]);hex(string);printf(" FILE ");hex(file);printf(" CFG ");hex(config);printf(" LOGFILE ");hex(logfile);printf(" LEVEL ");hex(level);putchar('\n');GNUNET_free(string);GNUNET_free(file);GNUNET_free(config);GNUNET_free(logfile);GNUNET_free(level);return 0;}
